Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Additional Material','Specimen is explicitly listed in an "Additional Material" or “Additional Material(s) Examined” section of a taxonomic description listing specimens that were examined by the taxonomist and listed as part of their concept of the scope of the taxon, but not designated as type specimens in the cited work.','Voucher',1);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Allotype','ICZN Glossary: Allotype:  A term, not regulated by the Code, for a designated specimen of opposite sex to the holotype','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Erroneous Citation','When entering “Cited As” determinations and comparing them to current determinations, errors within the publication sometimes become evident. We cannot correct the publication, but we should not leave obvious errors unremarked. Try to resolve error to correct type status if possible','Voucher',5);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Figured','The collection object is figured in the citation.','Voucher',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Genetic Voucher','The collection object is a voucher for genetic information presented in the citation.','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Holotype','ICZN 73.1. Holotypes. A holotype is the single specimen upon which a new nominal species-group taxon is based in the original publication','Primary',1);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Holotype (ms)','Cited in a manuscript.  No nomenclatural status.   Placeholder for pending publication types.','Voucher',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Ideotype','Not regulated by the Code,  opposite of topotype.  Cited specimen that doesn''t come from the type locality.','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Lectotype','ICZN 74.1. Designation of a lectotype. A lectotype may be designated from syntypes to become the unique bearer of the name of a nominal species-group taxon and the standard for its application (except in the case of hapantotypes [Art. 73.3]).','Primary',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Lectotype (ms)','Cited in a manuscript.  No nomenclatural status.   Placeholder for pending publication types.','Voucher',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Neotype','ICZN 75.1. Neotype: Definition. A neotype is the name-bearing type of a nominal species-group taxon designated under conditions specified in this Article when no name-bearing type specimen (i.e. holotype, lectotype, syntype or prior neotype) is believed to be extant and an author considers that a name-bearing type is necessary to define the nominal taxon objectively.','Primary',4);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Other Useful Citation','Lliterature that was helpful in researching data related to the specimen (agents, taxonomy, locality, etc.) that does not directly cite the specimen.','Voucher Not',5);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Paralectotype','ICZN 74.1.3. The valid designation of a lectotype permanently deprives all other specimens that were formerly syntypes of that nominal taxon of the status of syntype [Art. 73.2.2]; those specimens then become paralectotypes.','Secondary',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Paralectotype (ms)','Cited in a manuscript.  No nomenclatural status.   Placeholder for pending publication types.','Voucher',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Paratopotype','Review.  Paratypes (ICZN 72.4.5) that also happen to be from the type locality.','Secondary',4);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Paratype','ICZN 72.4.5. When an author designates a holotype [Art. 73.1], then the other specimens of the type series are paratypes.','Secondary',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Paratype (ms)','Cited in a manuscript.  No nomenclatural status.   Placeholder for pending publication types.','Voucher',2);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Plastoholotype (Paleontology)','A cast of a holotype specimen.','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Plastohypotype (Paleontology)','In Paleontology. A cast of a specimen of a species not of the original type series but known by published description, figure, or listing','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Plastoparatype (Paleontology)','In Paleontology. A cast of a paratype specimen.','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Plastotype (Paleontology)','A cast of a type specimen.','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Syntype','ICZN 73.2. Syntypes. Syntypes are specimens of a type series that collectively constitute the name-bearing type.','Primary',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Topotype','ICZN Glossary: topotype, n. (topotypic, a.)     A term, not regulated by the Code, for a specimen originating from the type locality of the species or subspecies to which it is thought to belong, whether or not the specimen is part of the type series.','Voucher',3);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('Voucher','A voucher specimen is a specimen mentioned in a publication serving as a basis of study and is retained as a reference in the collection. When a publication mentions a specimen as a type but it is not the paper that designated it as such, the citation type will still be “Voucher.” If there is something unique (e.g., first publication that  cited a catalog number where the original naming paper did not), this special indication would be put in remarks for the voucher citation.','Voucher',1);
Insert into CTCITATION_TYPE_STATUS (TYPE_STATUS,DESCRIPTION,CATEGORY,ORDINAL) values ('[type status needs research]','These type statuses require review and research and are likely verbatim transcriptions from ledgers and of unknown provenance','Temp',5);
